-- Replace the initial marketing-derived placeholders with the supplied current ICAN syllabus.
delete from public.ican_curriculum_templates;
insert into public.ican_curriculum_templates(code,title,level,modules)
select x->>'code',x->>'title',x->>'level',x->'modules' from jsonb_array_elements($json$
[{"code":"A1","title":"Business Environment","level":"Foundation","modules":["Business Processes and Environment","The Role of Accountancy in Business and Society","Management and Organisational Behaviour","Elements of Microeconomics and Macroeconomics","Technology and Data Analysis"]},{"code":"A2","title":"Financial Accounting","level":"Foundation","modules":["Accounting Framework","Recording Financial Transactions","Reconciliation in Financial Accounting","Accounting for Transactions in Financial Statements","Accounting for Partnership, Not-for-Profit Entities and Incomplete Records","Financial Statements","Computerised and Virtual Accounting Systems"]},{"code":"A3","title":"Management Accounting","level":"Foundation","modules":["Management Information","Accounting for Cost Elements","Costing Methods and Techniques","Forecasting, Budgeting and Budgetary Control","Standard Costing and Basic Variance Analysis","Decision-Making Techniques"]},{"code":"A4","title":"Corporate and Business Law","level":"Foundation","modules":["The Nigerian Legal and Court Systems","Partnerships and Business Name, and Company and Insolvency Laws","Criminal Law","Laws of Commercial Transactions","Employment Law","Law of Trusts and Administration of Estate","Alternative Dispute Resolution Mechanisms"]},{"code":"B1","title":"Financial Reporting","level":"Skills","modules":["Conceptual and Legal Frameworks for Financial Reporting","IFRS Accounting Standards and Policies Relating to Specific Transactions in Financial Statements","Preparation and Presentation of Single-Entity General Purpose Financial Statements","Preparing and Presenting Financial Statements of a Simple Group","Analysis and Interpretation of Financial Statements","Ethics, Current and Technological Developments in Financial Reporting"]},{"code":"B2","title":"Audit, Assurance and Forensics","level":"Skills","modules":["Introduction to Legal and Regulatory Frameworks of Audit and Assurance","Nature and Use of Internal Control (ISA 315 Revised)","Gathering Evidence and Audit Report","Forensic Accounting Services","Professional Ethics and Public Interest","Application of Technology in Audit, Assurance and Forensics"]},{"code":"B3","title":"Taxation","level":"Skills","modules":["Introduction to Taxation, Tax Administration and Ethics","Transaction Taxes","Personal Income Tax","Companies Income Tax","Application of Information Technology in Taxation"]},{"code":"B4","title":"Performance Management","level":"Skills","modules":["Management Information Systems and Data Analytics","Advanced Costing Techniques","Decision-Making Techniques","Budgeting and Control","Performance Measurement, Control and Management System","Performance Evaluation and Corporate Failure","Emerging Issues in Performance Management"]},{"code":"B5","title":"Financial Management","level":"Skills","modules":["Financial Management Function and Environment","Working Capital Management","Investment Appraisal","Business Finance","Business Valuations","Risk Management"]},{"code":"B6","title":"Public Sector Accounting and Finance","level":"Skills","modules":["Regulatory and Conceptual Frameworks of Public Sector Accounting","Planning and Budgeting","Report and Audit","Public Finance","Public Finance Management and Accountability","Sustainability and Sustainable Development"]},{"code":"C1","title":"Strategic Business Reporting","level":"Professional","modules":["Ethical Issues in, and Regulatory Framework of Strategic Business Reporting","Reporting of Entity's Performance to Stakeholders","Group Financial Statements","Interpretation of Financial Statements, Sustainability Disclosures, Non-Financial Data and Other Related Disclosures and Reports","Sustainability and Integrated Reporting","Impact of Changes and Potential Changes in Accounting Regulations","Other Current Developments in and Beyond Financial Reporting"]},{"code":"C2","title":"Advanced Audit, Assurance and Forensics","level":"Professional","modules":["Laws and Regulations on Audit and Assurance Engagements","Quality Management for Professional Firms and Engagements","Planning and Undertaking Audit Work","Drawing Conclusions and Reporting","Application of Information Technology in Auditing","Current Issues and Developments in Audit and Assurance"]},{"code":"C3","title":"Strategic Financial Management","level":"Professional","modules":["Introduction to Business Strategy and Financial Management","Strategic Management","Risk Management","Governance","Advanced Investment Appraisal","Acquisitions, Mergers, Corporate Reconstruction and Reorganisation","Advanced Risk Management Techniques"]},{"code":"C4","title":"Advanced Taxation","level":"Professional","modules":["Tax Administration","Taxation of Companies and Investment Income","International Taxation","Current Issues and Emerging Trends","Tax Management and Planning","Taxation of Incomes of Extractive Industries"]},{"code":"C5","title":"Case Study","level":"Professional","modules":["The Case Study Approach","Main Competences","Prior Knowledge","Assessment Procedure","Ethical and Professional Skepticism Consideration","Detailed Contents","Scenario Requirements","Analytical Tools"]}]
$json$::jsonb) x;

create or replace function public.import_ican_curriculum(p_tutor uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_uid uuid:=public.require_active_session();t ican_curriculum_templates;m jsonb;c uuid;mid uuid;pos integer;n integer:=0;
begin
 if not public.is_admin() or not exists(select 1 from profiles where id=p_tutor and role='tutor' and status='active') then raise exception 'Choose an active tutor as administrator.' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtext('ican-curriculum-import'));
 for t in select * from ican_curriculum_templates order by code loop
  if exists(select 1 from courses where code=t.code) then continue;end if;
  insert into courses(code,title,level,description) values(t.code,t.title,t.level,'ICAN '||t.level||' examination preparation.') returning id into c;
  insert into course_tutors(course_id,user_id,assigned_by) values(c,p_tutor,v_uid);
  pos:=0;for m in select * from jsonb_array_elements(t.modules) loop pos:=pos+1;insert into modules(course_id,title,position) values(c,m#>>'{}',pos) returning id into mid;end loop;n:=n+1;
 end loop;
 perform public.log_audit('ican_curriculum_imported','profile',p_tutor,jsonb_build_object('courses',n));return jsonb_build_object('created',n);
end $$;
